document.addEventListener("DOMContentLoaded",(async()=>{const t=document.getElementById("accountNavLink");if(!t||!window.RotimaticApi)return;const n='<svg class="nav-account-icon" viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';try{const a=await RotimaticApi.me();a&&a.data&&a.data.authenticated&&(t.innerHTML=`${n}<span>Account</span>`,t.href="dashboard.html",t.title="Open My Account",t.classList.add("is-auth"))}catch(a){t.innerHTML=`${n}<span>Login</span>`,t.href="login.html",t.title="Account Login",t.classList.remove("is-auth")}}));